"""Exact built-in key-pose prompt and original-reference lineage."""
import produce as p
def main():
 image=p.SOURCE_DIR/'walk_contact_original.png';prompt=p.SOURCE_DIR/'walk_contact_prompt.txt';reference=p.SOURCE_DIR/'accepted_idle_reference.png'
 prompt.write_text('Use case precise-object-edit. Make ONE original animation key pose for this exact fantasy game character. Preserve youthful face, pointed charcoal hood, mustard scarf, riveted steel armor, brown belts and bolt quiver, gray split coat, exactly two arms/two legs, exact compact wooden crossbow and original painted pixel-detailed style, elevated orthographic three-quarter camera facing right. Change pose only: calm WALK forward contact, right/near leg extends forward to SCREEN RIGHT heel on ground, left/far leg extends backward to SCREEN LEFT toe on ground, modest human stride, no running/knee-high march. Both gloved hands carry the original compact crossbow LOW at waist, muzzle/front bow tilted down 45 degrees toward ground, not aiming. Near/right hand holds rear stock, far/left hand supports fore-end. Stable unchanged anatomy, visible natural knees/ankles, original adult stature. Full body including entire bow and both boots. Transparent background, no text, no shadows, no floor, no flying bolts, no motion effects. One figure only, no sheet.\n',encoding='utf-8')
 def record(path):return dict(path=path.relative_to(p.ROOT).as_posix(),sha256=p.sha(path))
 p.write(image.with_suffix('.generation.json'),dict(tool='built-in image_gen',image=record(image),prompt=record(prompt),references=[record(reference)],source_wide_scale=.155,review='One reviewed original forward-contact reference with original low carry. Two opposed-contact attempts failed to swap leg phases and were rejected; not used as authored gait phases.'))
if __name__=='__main__':main()
